# %% ../notebooks/07_pipeline.ipynb #07_pipeline-14
class Pipeline:
    """Evaluate fresh model instances on independent, seeded scenarios.

    Native models implement fit(context: DataFrame) and predict(future_index),
    returning a Forecast. Supply a native class, a model_factory producing a
    fresh unfitted instance, or an instance implementing clone_unfitted().
    sklearn regressors/transformers can be added with add().
    Only recursive sklearn reduction is supported in this focused release.
    """

    def __init__(self, model=None, window_length=12, strategy="recursive", *, model_factory=None):
        if strategy != "recursive":
            raise ValueError("This release supports strategy='recursive' only")
        self.model = model
        if model is not None and model_factory is not None:
            raise ValueError("Specify model or model_factory, not both")
        if model_factory is not None and not callable(model_factory):
            raise TypeError("model_factory must be a callable producing a fresh unfitted model")
        self.model_factory = model_factory
        if isinstance(window_length, (bool, np.bool_)) or not isinstance(window_length, (int, np.integer)) or window_length < 1:
            raise ValueError("window_length must be a positive integer")
        self.window_length = int(window_length)
        self.strategy = strategy
        self.steps = []

    def add(self, estimator, **parameters):
        """Add an sklearn transformer or final regressor; returns self."""
        if self.model is not None or self.model_factory is not None:
            raise ValueError("Use a native model or sklearn steps, not both")
        if inspect.isclass(estimator):
            estimator = estimator(**parameters)
        elif parameters:
            estimator = fresh_model(estimator).set_params(**parameters)
        self.steps.append(estimator)
        return self

    def _model(self):
        if self.steps:
            return SklearnForecaster(self.steps, self.window_length)
        if self.model is None and self.model_factory is None:
            return NaiveForecaster()
        newly_constructed = self.model_factory is not None or inspect.isclass(self.model)
        candidate = self.model_factory() if self.model_factory is not None else (self.model() if inspect.isclass(self.model) else self.model)
        if callable(getattr(candidate, "clone_unfitted", None)):
            return candidate if newly_constructed else fresh_model(candidate)
        if is_sklearn_regressor(candidate):
            return SklearnForecaster([candidate], self.window_length)
        return candidate if newly_constructed else fresh_model(candidate)

    def to_config(self):
        """Return JSON-safe configuration and whether safe automatic replay is supported."""
        from timegym.provenance import pipeline_config
        return pipeline_config(self)

    @classmethod
    def from_config(cls, config):
        """Reconstruct only an allowlisted built-in model, without dynamic imports."""
        from timegym.provenance import pipeline_from_config
        return pipeline_from_config(config)

    def predict(self, context, future_index):
        """Fit on context and predict the supplied index, without future targets."""
        if isinstance(context, pd.Series):
            context = context.to_frame(name=context.name if context.name is not None else "y")
        # Share the public task contract, including unique target names.
        ForecastTask(context=context, future_index=future_index)
        model = self._model()
        model.fit(context.copy(deep=True))
        forecast = model.predict(future_index.copy())
        if not isinstance(forecast, Forecast):
            raise TypeError("Native model.predict must return a timegym.Forecast")
        return forecast

    def run(self, scenarios=None, seeds=(0, 1, 2), *, check_dependence=False,
            n_calibration=99, alpha=0.05, dependence_seed_offset=100_000):
        """Evaluate once per case and retain the data, forecast, and diagnostics.

        ``run.report`` provides the unchanged serializable report interface;
        ``run.plot_forecasts()`` and ``run.plot_errors()`` inspect these exact
        outputs without additional fitting or predictive sampling.
        """
        from timegym.provenance import diagnostic_settings, runtime_provenance
        settings = diagnostic_settings(check_dependence=check_dependence, n_calibration=n_calibration,
                                       alpha=alpha, dependence_seed_offset=dependence_seed_offset)
        if scenarios is None:
            scenarios = [Scenario(kind) for kind in ("white_noise", "trend", "seasonal", "ar1", "random_walk")]
        scenarios, seeds = list(scenarios), list(seeds)
        if not scenarios or not seeds:
            raise ValueError("Provide at least one scenario and one seed")
        results = []
        for scenario_index, scenario in enumerate(scenarios):
            for seed_index, seed in enumerate(seeds):
                case = scenario.generate(seed=seed)
                forecast = None
                try:
                    forecast = self.predict(case.task.context, case.task.future_index)
                    result = evaluate_forecast(case, forecast, check_dependence=check_dependence,
                                               dependence_seed=int(seed) + dependence_seed_offset,
                                               n_calibration=n_calibration, alpha=alpha)
                except Exception as exc:
                    result = CaseResult(scenario=scenario.kind, seed=int(seed), diagnostics=[
                        DiagnosticResult(name="model_execution", status="ERROR", category="execution",
                                         message=f"{type(exc).__name__}: {exc}",
                                         evidence=exception_evidence(exc))],
                        metrics={}, manifest=case.manifest)
                results.append(EvaluatedCase(case=case, forecast=forecast, result=result,
                                             scenario_index=scenario_index, seed_index=seed_index))
        return ForecastRun(cases=results, metadata={**runtime_provenance(), "numpy": np.__version__,
                          "pandas": pd.__version__, "model": ("SklearnForecaster" if self.steps else
                              getattr(self.model_factory, "__qualname__", "model_factory") if self.model_factory is not None else
                              self.model.__name__ if inspect.isclass(self.model) else
                              type(self.model).__name__ if self.model is not None else "NaiveForecaster"),
                          "window_length": self.window_length, "strategy": self.strategy,
                          "pipeline_config": self.to_config(), "diagnostic_settings": settings})

    def test(self, scenarios=None, seeds=(0, 1, 2), *, check_dependence=False,
             n_calibration=99, alpha=0.05, dependence_seed_offset=100_000):
        """Return a machine-readable TestReport; statistical uncertainty is explicit."""
        return self.run(scenarios, seeds=seeds, check_dependence=check_dependence,
                        n_calibration=n_calibration, alpha=alpha,
                        dependence_seed_offset=dependence_seed_offset).report

    def plot_tests(self, scenarios=None, seeds=(0, 1, 2), *, show_quantiles=False,
                   figsize=None, **diagnostic_settings):
        """Fit a display suite and return its forecast matrix Figure.

        Display defaults use 240 context observations and 80 forecast steps;
        ``test`` and ``run`` retain their existing scenario defaults. To make
        several figures from the same fits, use ``run`` and its plot methods.
        """
        if scenarios is None:
            scenarios = [Scenario(kind, context_length=240, horizon=80)
                         for kind in ("white_noise", "trend", "seasonal", "ar1", "random_walk")]
        return self.run(scenarios, seeds=seeds, **diagnostic_settings).plot_forecasts(
            show_quantiles=show_quantiles, figsize=figsize)

    def plot_error(self, scenarios=None, seeds=tuple(range(20)), *, metric="mean_reference_mse",
                   bins=None, missing="raise", figsize=None, **diagnostic_settings):
        """Fit once per requested case and plot the retained score distribution.

        This convenience call evaluates a new run. Use an existing run's
        ``plot_errors`` method to inspect previously evaluated forecasts.
        """
        return self.run(scenarios, seeds=seeds, **diagnostic_settings).plot_errors(
            metric=metric, bins=bins, missing=missing, figsize=figsize)
